import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = list(reader)

    if not records:
        return {"columns": [], "rows": []}

    width = max(17, max((len(record) for record in records), default=0))
    columns = list(records[0])

    while len(columns) < width:
        columns.append(f"Column {len(columns) + 1}")

    rows = []
    for record in records[1:]:
        row = list(record)
        row.extend([""] * (width - len(row)))
        rows.append(row)

    return {"columns": columns, "rows": rows}
